// Détection IP simplifiée (sans modules interdits)
const webhookData = $input.item.json;

// IP par défaut ou depuis les headers
const possibleIPs = [
  '192.168.1.15',
  '192.168.1.59', 
  '127.0.0.1'
];

// Port par défaut
const flaskPort = 5003;

// Construire l'URL dynamiquement
const flaskIP = possibleIPs[0]; // Premier IP de la liste
const flaskConfig = {
  ip: flaskIP,
  port: flaskPort,
  url: `http://${flaskIP}:${flaskPort}`
};

console.log('🌐 Configuration Flask détectée:', flaskConfig);
console.log('📥 Données webhook reçues:', Object.keys(webhookData));

// Valider les données requises
const requiredFields = ['contenu', 'image_urls'];
const missingFields = requiredFields.filter(field => !webhookData[field]);

if (missingFields.length > 0) {
  throw new Error(`Champs manquants: ${missingFields.join(', ')}`);
}

// Traiter les URLs d'images
let imageUrls = [];
if (typeof webhookData.image_urls === 'string') {
  imageUrls = webhookData.image_urls.split(',').map(url => url.trim()).filter(url => url);
} else if (Array.isArray(webhookData.image_urls)) {
  imageUrls = webhookData.image_urls.filter(url => url && url.trim());
}

console.log(`📸 ${imageUrls.length} images détectées:`, imageUrls);

return {
  json: {
    contenu: webhookData.contenu,
    image_urls: imageUrls,
    flask_config: flaskConfig,
    dynamic_urls: {
      create_layout: `${flaskConfig.url}/api/create-layout-urls`,
      download_base: `${flaskConfig.url}/api/download/`
    },
    webhook_data: webhookData
  }
};

// Traitement final : combiner IA + Webhook + Config Flask
const aiResponse = $input.item.json.text;
const webhookData = $node["🌐 Détecteur Simple"].json;

console.log('🔧 Configuration Flask:', webhookData.flask_config);
console.log('🤖 Réponse IA brute:', aiResponse);

// Parser la réponse JSON d'OpenAI
let analysis;
try {
  const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
  analysis = JSON.parse(cleanResponse);
  console.log('✅ Analyse IA parsée:', analysis);
} catch (e) {
  console.log('❌ Erreur parsing IA:', e.message);
  analysis = {
    title: 'Titre générique',
    subtitle: 'Sous-titre générique',
    body: webhookData.contenu
  };
}

// Compter les images
const imageCount = webhookData.image_urls.length;
const imageUrls = webhookData.image_urls;

// Sélectionner le template selon le nombre d'images
let template;
if (imageCount === 1) {
  template = 'template-mag-simple-1808';
} else if (imageCount >= 2) {
  template = 'template-mag-simple-2-1808';
} else {
  template = 'template-mag-simple-1808';
}

console.log(`📋 Template sélectionné: ${template} (${imageCount} images)`);

return {
  json: {
    ai_analysis: {
      title: analysis.title,
      subtitle: analysis.subtitle,
      body: analysis.body
    },
    template_selection: {
      template: template,
      image_count: imageCount,
      reason: `${imageCount} image(s) détectée(s)`
    },
    image_data: {
      urls: imageUrls,
      count: imageCount
    },
    flask_config: webhookData.flask_config,
    dynamic_urls: webhookData.dynamic_urls,
    original_content: webhookData.contenu,
    debug: {
      ai_raw_response: aiResponse,
      webhook_received: Object.keys(webhookData.webhook_data)
    }
  }
};

